package com.aistock.market.calendar;
import static com.aistock.market.calendar.CalendarRecords.*;
import com.aistock.common.BusinessException;
import com.aistock.market.support.MarketDatabaseFixture;
import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class CalendarMysqlTest {
 final Clock clock=Clock.fixed(Instant.parse("2026-10-10T06:00:00Z"),ZoneOffset.UTC);
 Candidate candidate(LocalDate start,LocalDate end,Instant fetched){var days=new ArrayList<Day>();for(var d=start;!d.isAfter(end);d=d.plusDays(1))days.add(new Day(d,d.getDayOfWeek()!=DayOfWeek.SATURDAY&&d.getDayOfWeek()!=DayOfWeek.SUNDAY));return new Candidate("baostock",start,end,fetched,CalendarService.hash(days),days);}
 Request request(String id){return new Request(id,LocalDate.of(2026,10,8),LocalDate.of(2026,10,12));}
 @Test void refreshReplaysAndConflictsWithoutNewSourceCalls(){var f=new MarketDatabaseFixture();var calls=new AtomicInteger();var service=new CalendarService(f.jdbc(),r->{calls.incrementAndGet();return candidate(r.start(),r.end(),clock.instant());},clock,7);var r=request("calendar-good");var result=service.refresh(r);assertEquals(result,service.refresh(r));assertEquals(1,calls.get());assertEquals(5,service.current().candidate().days().size());assertEquals("CALENDAR_OPERATION_CONFLICT",assertThrows(BusinessException.class,()->service.refresh(new Request(r.operationId(),r.start(),r.end().plusDays(1)))).code());}
 @Test void badSourceAndInvalidHashKeepPublishedVersion(){var f=new MarketDatabaseFixture();var good=candidate(request("x").start(),request("x").end(),clock.instant());var service=new CalendarService(f.jdbc(),r->good,clock,7);var saved=service.refresh(request("good"));var bad=new Candidate(good.provider(),good.start(),good.end(),good.fetchedAt(),"a".repeat(64),good.days());assertThrows(BusinessException.class,()->new CalendarService(f.jdbc(),r->bad,clock,7).refresh(request("bad")));assertThrows(BusinessException.class,()->new CalendarService(f.jdbc(),r->{throw new IllegalStateException("fixture");},clock,7).refresh(request("unavailable")));assertEquals(saved.versionId(),service.current().versionId());}
 @Test void expiredOrIncompleteCoverageCannotSupplyBoundary(){var f=new MarketDatabaseFixture();var c=candidate(request("x").start(),request("x").end(),clock.instant());var service=new CalendarService(f.jdbc(),r->c,clock,7);service.refresh(request("coverage"));assertTrue(service.covering(LocalDate.of(2026,10,9),LocalDate.of(2026,10,10)).isPresent());assertTrue(service.covering(LocalDate.of(2026,10,9),LocalDate.of(2026,10,13)).isEmpty());var late=new CalendarService(f.jdbc(),r->c,Clock.offset(clock,Duration.ofDays(8)),7);assertTrue(late.covering(c.start(),c.end()).isEmpty());}
 @Test void delayedResponseDoesNotMoveHeadBackwards(){var f=new MarketDatabaseFixture();var latest=candidate(request("x").start(),request("x").end(),clock.instant());var recent=new CalendarService(f.jdbc(),r->latest,clock,7).refresh(request("recent"));var older=candidate(latest.start(),latest.end(),clock.instant().minusSeconds(60));var delayed=new CalendarService(f.jdbc(),r->older,clock,7);var old=delayed.refresh(request("delayed"));assertNotEquals(recent.versionId(),old.versionId());assertEquals(recent.versionId(),delayed.current().versionId());}
 @Test void gapDuplicateAndNullFlagsAreRejected(){var f=new MarketDatabaseFixture();var c=candidate(request("x").start(),request("x").end(),clock.instant());for(int kind=0;kind<3;kind++){var days=new ArrayList<>(c.days());if(kind==0)days.remove(2);if(kind==1)days.set(2,days.get(1));if(kind==2)days.set(2,new Day(days.get(2).date(),null));var bad=new Candidate(c.provider(),c.start(),c.end(),c.fetchedAt(),c.sourcePayloadHash(),days);assertThrows(BusinessException.class,()->new CalendarService(f.jdbc(),r->bad,clock,7).refresh(request(UUID.randomUUID().toString())));}}
 @Test void concurrentSameOperationPublishesOnlyOneVersion()throws Exception{var f=new MarketDatabaseFixture();var latch=new java.util.concurrent.CountDownLatch(2);var service=new CalendarService(f.jdbc(),r->{latch.countDown();try{if(!latch.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("concurrency timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return candidate(r.start(),r.end(),clock.instant());},clock,7);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var a=pool.submit(()->service.refresh(request("concurrent")));var b=pool.submit(()->service.refresh(request("concurrent")));assertEquals(a.get(10,java.util.concurrent.TimeUnit.SECONDS).versionId(),b.get(10,java.util.concurrent.TimeUnit.SECONDS).versionId());assertEquals(1,f.jdbc().queryForObject("select count(*) from independent_calendar_version",Integer.class));}finally{pool.shutdownNow();}}
 @Test void futureSubsetCannotHideStillUsableHistoricalCoverage(){var f=new MarketDatabaseFixture();var original=candidate(LocalDate.of(2026,10,8),LocalDate.of(2026,11,9),clock.instant().minusSeconds(60));var service=new CalendarService(f.jdbc(),r->original,clock,7);var saved=service.refresh(new Request("full",original.start(),original.end()));var future=candidate(LocalDate.of(2026,11,1),LocalDate.of(2026,11,9),clock.instant());var updated=new CalendarService(f.jdbc(),r->future,clock,7);updated.refresh(new Request("future",future.start(),future.end()));assertEquals(saved.versionId(),updated.covering(LocalDate.of(2026,10,9),LocalDate.of(2026,10,10)).orElseThrow().versionId());}
 @Test void longRangeRefreshRemainsReadableWhenFutureShortHeadIsRetained(){
 var f=new MarketDatabaseFixture();var shortService=new CalendarService(f.jdbc(),r->candidate(r.start(),r.end(),clock.instant().minusSeconds(60)),clock,7);
 var head=shortService.refresh(new Request("short-future",LocalDate.of(2026,7,1),LocalDate.of(2026,11,9)));
 var service=new CalendarService(f.jdbc(),r->candidate(r.start(),r.end(),clock.instant()),clock,7);
 var full=service.refresh(new Request("full-history",LocalDate.of(2025,10,9),LocalDate.of(2026,10,10)));
 assertEquals(head.versionId(),service.current().versionId());
 assertEquals(full.versionId(),service.covering(LocalDate.of(2025,10,9),LocalDate.of(2026,10,10)).orElseThrow().versionId());
 }
}
